using System;
using System.Collections.Generic;
using System.Web;
using System.Web.UI;
using System.Web.UI.WebControls;
using DNAide.Web;
using DNAide.Core;
using DNAide.Data;
using System.Data;
using Sunplus.Accounting.Core.Cache;
using Sunplus.Accounting.Core.Common;
using Sunplus.Accounting.Core.Web;

public partial class Report_HRRaceResult : Page
{

    protected void Page_Load(object sender, EventArgs e)
    {
        int leagueid = CastAide.AsInt32(Request.QueryString["leagueid"], 0); ;
        string raceno = CastAide.AsString(Request.QueryString["raceno"], string.Empty);
        string eventdate = CastAide.AsString(Request.QueryString["eventdate"], string.Empty);
        lHRRaceResult.Text = GenHTMLHRRaceResult(leagueid, raceno, eventdate);

    }

    private string GenHTMLHRRaceResult(int leagueid, string raceno, string eventdate)
    {
        string tplRaceResult = "";
        if (0 == leagueid || string.IsNullOrEmpty(raceno))
        {
            //Assign No Information
            tplRaceResult = Sunplus.Accounting.Core.Web.WebUtils.LoadTemplate("Report/HRRaceResultNoInfo.htm");
            //Assign header
            TemplateHandler.Assign(ref tplRaceResult, "{lblSportName}", Resources.Language.HR);
            TemplateHandler.Assign(ref tplRaceResult, "lblMeetingName", string.Empty);
            TemplateHandler.Assign(ref tplRaceResult, "lblRace", Resources.Language.Race);
            TemplateHandler.Assign(ref tplRaceResult, "lblPlace", Resources.Language.Place);
            TemplateHandler.Assign(ref tplRaceResult, "lblHorseNo", Resources.Language.HorseNo);
            TemplateHandler.Assign(ref tplRaceResult, "noinfo", Resources.Language.thereisnodata);
        }
        else
        {
            var dbRaceResult = Sunplus.Accounting.DataAccess.IBCDLL.Accounting.AccountReport.HRRaceResult(leagueid, raceno, eventdate);
            if (dbRaceResult == null || dbRaceResult.Tables[0].Rows.Count < 0)
            {
                //Assign No Information
                tplRaceResult = Sunplus.Accounting.Core.Web.WebUtils.LoadTemplate("Report/HRRaceResultNoInfo.htm");
                //Assign header
                TemplateHandler.Assign(ref tplRaceResult, "{lblSportName}", Resources.Language.HR);
                TemplateHandler.Assign(ref tplRaceResult, "lblMeetingName", string.Empty);
                TemplateHandler.Assign(ref tplRaceResult, "lblRace", Resources.Language.Race);
                TemplateHandler.Assign(ref tplRaceResult, "lblPlace", Resources.Language.Place);
                TemplateHandler.Assign(ref tplRaceResult, "lblHorseNo", Resources.Language.HorseNo);
                TemplateHandler.Assign(ref tplRaceResult, "noinfo", Resources.Language.thereisnodata);
            }
            else
            {
                tplRaceResult = Sunplus.Accounting.Core.Web.WebUtils.LoadTemplate("Report/HRRaceResult.htm");
                string tplData = TemplateHandler.CopyBlock(tplRaceResult, "data");
                int totalPlace = 1;
                string htmlData = "";

                //Assign header
                TemplateHandler.Assign(ref tplRaceResult, "{lblSportName}", Resources.Language.HR);
                TemplateHandler.Assign(ref tplRaceResult, "lblMeetingName", "- " + CacheRef.GetLeagueName(leagueid));
                TemplateHandler.Assign(ref tplRaceResult, "lblRace", Resources.Language.Race);
                TemplateHandler.Assign(ref tplRaceResult, "lblPlace", Resources.Language.Place);
                TemplateHandler.Assign(ref tplRaceResult, "lblHorseNo", Resources.Language.HorseNo);
                foreach (DataRow row in dbRaceResult.Tables[0].Rows)
                {
                    totalPlace++;
                    string tmpData = tplData;
                    TemplateHandler.Assign(ref tmpData, "place", AccCommon.GetPlaceFormat(CastAide.AsInt32(row["placing"], 0)));
                    TemplateHandler.Assign(ref tmpData, "horseno", row["matchcode"] + ". " + CacheRef.GetHorseTeamName(row["teamid"]));
                   
                    htmlData += tmpData;
                }                
                TemplateHandler.Assign(ref tplRaceResult, "racename", raceno);
                TemplateHandler.Assign(ref tplRaceResult, "totalplace", totalPlace);
                TemplateHandler.ReplaceBlock(ref tplRaceResult, "data", htmlData);
            }

            // for SCR Info
            if (CastAide.AsString(Request["HRBettype"]) == "1")
            {
                string htmlDataSCR = "";
                string tplRaceResultSCR = Sunplus.Accounting.Core.Web.WebUtils.LoadTemplate("Report/HRRaceResultBLSCR.htm");
                TemplateHandler.Assign(ref tplRaceResultSCR, "lblHorseNo", Resources.Language.HorseNo);
                DataRowCollection dtRowSCR = dbRaceResult.Tables[1].Rows;
                if (dtRowSCR.Count > 0)
                {
                    string tplDataSCR = TemplateHandler.CopyBlock(tplRaceResultSCR, "data");
                    foreach (DataRow row in dtRowSCR)
                    {
                        string tmpDataSCR = tplDataSCR;
                        TemplateHandler.Assign(ref tmpDataSCR, "vHorseno", row["matchcode"] + ". " + CacheRef.GetHorseTeamName(row["teamid"]));
                        TemplateHandler.Assign(ref tmpDataSCR, "vTime", CastAide.AsString(row["SCRTime"]) == "" ? "" : CastAide.AsString(CastAide.AsDateTime(row["SCRTime"]).TimeOfDay));
                        TemplateHandler.Assign(ref tmpDataSCR, "vDeduct", CastAide.AsString(CastAide.AsInt16(row["Deduction"])) + "%");
                        htmlDataSCR += tmpDataSCR;
                    }
                    TemplateHandler.ReplaceBlock(ref tplRaceResultSCR, "data", htmlDataSCR);
                }
                else
                {
                    return tplRaceResult;
                    //htmlDataSCR = Sunplus.Accounting.Core.Web.WebUtils.LoadTemplate("NoInformation.tpl");
                    //TemplateHandler.Assign(ref htmlDataSCR, "tdno", "3");
                    //TemplateHandler.Assign(ref htmlDataSCR, "nodata", Resources.Language.thereisnodata);
                    //TemplateHandler.ReplaceBlock(ref tplRaceResultSCR, "data", htmlDataSCR);
                }
                tplRaceResult += tplRaceResultSCR;
            }
        }
        return tplRaceResult;
    }
}
